    "content": "7月19日至26日，第七届“中外人文交流小使者”全国总展示在复旦大学启幕。 教育部中外人文交流中心副主任张学仁，复旦大学校长助理吴立波，中国艺术教育促进会常务副秘书长、“中外人文交流小使者”专家指导委员会主任王军来到现场，苏格兰皇家音乐学院舞蹈系主任Kerry Livingstone也跨洋而来，共同见证属于青少年的闪耀时刻。 上海黄浦区活动中心的乐团率先奏响音符，气势昂扬；武汉钢花的音诗画深情呈现，朗诵与画面交融，直击人心；徐汇区活动中心的京剧更是炸场，小使者们水袖翩跹、唱腔婉转，台步稳健如行云流水，现场掌声久久不…"
