    "author": "杨洋",
    "description": "在韩国釜山举行的联合国教科文组织第48届世界遗产大会7月25日通过决议，将“景德镇手工瓷业遗存”列入《世界遗产名录》。至此，中国世界遗产总数达到61项。 以泥为骨，以火为魂，瓷的故事在这里扎根。千年窑火从未冷却，让世界看见属于中国瓷器的风雅。这就是景德镇。 记者：彭菁 视频制作：杨洋",
