    "content": "日本全国微型车协会联合会会长赤间俊一表示，欢迎中国汽车巨头比亚迪进入日本微型车市场，指这虽然对日本车企形成竞争，但希望共同带动行业发展。 据比亚迪日本官网，该企业将于下周二（28日）在日本正式发布纯电轻型汽车“RACCO”（日文意为海獭）。据共同社，日本全国微型车协会介绍，虽有过欧洲企业2001年推出微型车等先例，但海外厂商涉足这一市场仍属罕见。 日本微型车协会联合会会长赤间俊一接受共同社访问时说，欢迎中国汽车巨头比亚迪（BYD）进入这一市场，并称“这是对微型车未来前景的认可，令人欣喜”。他还表示，虽然对日本车企来…"
