    "description": "中新网7月25日电 据“自然资源部”微信公众号消息，据气象部门预测和自然资源部地质灾害技术指导中心研判，受今年第12号台风影响，江西西南部、湖南东南部、广东东南部和北部等局部地区发生地质灾害的风险高。自然资源部于7月25日11时对江西、湖南启动地质灾害防御IV级响应，将广东地质灾害防御响应等级由IV级提升为Ⅲ级。",
    "content": "中新网7月25日电 据“自然资源部”微信公众号消息，据气象部门预测和自然资源部地质灾害技术指导中心研判，受今年第12号台风影响，江西西南部、湖南东南部、广东东南部和北部等局部地区发生地质灾害的风险高。自然资源部于7月25日11时对江西、湖南启动地质灾害防御IV级响应，将广东地质灾害防御响应等级由IV级提升为Ⅲ级。"
