    "content": "中新网7月25日电 据“自然资源部”微信公众号消息，今年第12号台风“红霞”已加强为台风级，国家海洋环境预报中心发布近岸海浪红色警报和风暴潮橙色警报。根据《海洋灾害应急预案》规定，自然资源部于7月25日9时将对广东省的海洋灾害应急响应级别提升至二级，维持对福建省的海洋灾害四级应急响应。"
