    "description": "台湾云林县一只送宰羊只被检出戴奥辛超标，是当地首次在肉品中发现这类污染物。初步调查显示，问题羊肉并未出售，相关牧场供应的生羊乳已预防性下架。 据台湾《联合报》报道，台湾云林县政府本周四（7月23日）接获农业部通报，云林肉品市场一件羊肉抽验检出戴奥辛超标，周五（24日）下午再接获食药署通知复验结果为阳性，成为云林首件肉品检出戴奥辛超标案例。 戴奥辛是一类在垃圾不完全燃烧、金属冶炼及部分工业生产过程中可能产生的持久性污染物，不易分解并容易累…",
    "content": "台湾云林县一只送宰羊只被检出戴奥辛超标，是当地首次在肉品中发现这类污染物。初步调查显示，问题羊肉并未出售，相关牧场供应的生羊乳已预防性下架。 据台湾《联合报》报道，台湾云林县政府本周四（7月23日）接获农业部通报，云林肉品市场一件羊肉抽验检出戴奥辛超标，周五（24日）下午再接获食药署通知复验结果为阳性，成为云林首件肉品检出戴奥辛超标案例。 戴奥辛是一类在垃圾不完全燃烧、金属冶炼及部分工业生产过程中可能产生的持久性污染物，不易分解并容易累积在动物脂肪及食物链中。世界卫生组织指出，长期或大量接触戴奥辛，可能影响人体免疫…"
