    "content": "新华社北京7月25日电 日本执政党自由民主党近日再曝金钱丑闻。该党位于福冈县的分支机构被指要求出任该县议长和副议长的成员“进贡”大额资金，其中一名前议长自曝被索要2000万日元（约合83万元人民币）。 据日本《读卖新闻》、朝日电视台等多家媒体24日报道，福冈县前议长吉松源昭向媒体揭发这一丑闻。吉松源昭自述，他2020年6月出任县议长前，其所属的自民党福冈县议员团以各种名义向其索要金钱，包括党派社交活动的打高尔夫球费用、住宿费、交通费和高级餐厅餐饮费等，共计约2000万日元。他还公开了福冈县议员团重要人物中尾正幸向其…"
