    "content": "新华社北京7月25日电 健怡可乐一向在印度市场热销，卖得最多的是300毫升铝罐装。然而，伊朗战事延宕扰乱铝罐供应链，可口可乐公司不得不调整进口源，推出330毫升铝罐装，并上调售价。媒体认为，这一案例表明，受伊朗战事影响，不少企业正被迫调整供应链以及在主要消费市场提高售价。 2023年4月26日，人们聚集在印度新德里的一处市场。新华社发（贾韦德·达尔摄） 路透社24日以两名知情人士为消息源报道，由于300毫升容量的铝罐供应紧张，可口可乐公司被迫从东南亚采购成本更高的330毫升铝罐。原先，印度市场最热销的300毫升健怡…"
