    "description": "7月25日，在韩国釜山举行的联合国教科文组织第48届世界遗产大会上，中国申报的“景德镇手工瓷业遗存”通过审议，成功列入《世界遗产名录》。这是中国陶瓷文化首次以完整的手工瓷业遗存体系列入《世界遗产名录》。 “景德镇手工瓷业遗存”由5个组成部分构成，即镇区瓷业生产中心、湖田古瓷窑址、高岭瓷土矿遗址、长岭瓷石矿遗址和蛟潭窑柴燃料产区，包含御窑厂窑址等15组遗产构成要素，共45个遗产点位。 新华社记者实地探访，带你走进高岭瓷土矿遗址。 高岭，江…",
    "content": "7月25日，在韩国釜山举行的联合国教科文组织第48届世界遗产大会上，中国申报的“景德镇手工瓷业遗存”通过审议，成功列入《世界遗产名录》。这是中国陶瓷文化首次以完整的手工瓷业遗存体系列入《世界遗产名录》。 “景德镇手工瓷业遗存”由5个组成部分构成，即镇区瓷业生产中心、湖田古瓷窑址、高岭瓷土矿遗址、长岭瓷石矿遗址和蛟潭窑柴燃料产区，包含御窑厂窑址等15组遗产构成要素，共45个遗产点位。 新华社记者实地探访，带你走进高岭瓷土矿遗址。 高岭，江西浮梁县一条山脉的名字，就是这座不起眼的山，给了全世界白色陶土一个统一的称呼。 …"
