    "description": "新华社北京7月25日电 欧洲央行首席经济学家菲利普·莱恩日前就美国对一些贸易伙伴征收新关税发表评论说，欧洲经济主要依靠内需支撑，欧美之间的贸易固然重要，但“并非主导问题”。 彭博社报道，莱恩在爱尔兰参加一场活动时表示，“美国并非国际贸易主导力量”，欧洲面向全世界进行贸易，而不仅仅是美国。美国贸易代表办公室23日发布公告，宣布依据《1974年贸易法》第301条，以所谓“强迫劳动”为名对60个国家和地区征收10%至12.5%的关税，以替代2…",
    "content": "新华社北京7月25日电 欧洲央行首席经济学家菲利普·莱恩日前就美国对一些贸易伙伴征收新关税发表评论说，欧洲经济主要依靠内需支撑，欧美之间的贸易固然重要，但“并非主导问题”。 彭博社报道，莱恩在爱尔兰参加一场活动时表示，“美国并非国际贸易主导力量”，欧洲面向全世界进行贸易，而不仅仅是美国。美国贸易代表办公室23日发布公告，宣布依据《1974年贸易法》第301条，以所谓“强迫劳动”为名对60个国家和地区征收10%至12.5%的关税，以替代24日到期的全球进口关税。 莱恩表示，当前中东战事对欧洲经济产生的影响是“中等程度…"
