    "content": "新华社洛杉矶7月24日电（记者高山）派拉蒙天舞公司24日宣布同意推迟收购华纳兄弟探索公司的交易。该项被广泛认为将改变美国娱乐、媒体等多个行业格局的交易目前正面临严峻法律挑战。 以加利福尼亚州为首的美国12个州13日向加州北区联邦地区法院提起诉讼，要求阻止这项总额预计高达约1110亿美元的收购。民主党籍的加州总检察长罗布·邦塔在宣布提起诉讼的声明中说，这两家娱乐业巨头合并将削弱美国影视业合理竞争并损害消费者利益。 加州北区联邦地区法院法官阿拉塞利·马丁内斯-奥尔金20日发布临时限制令，暂停派拉蒙天舞对华纳兄弟探索公司…"
