    "content": "中国官方通报，中国提交的“景德镇手工瓷业遗存”项目申遗成功，星期六列入《世界遗产名录》，为历时11年的申遗工作画上句点。 据中国国家文物局微信公众号消息，中国提交的“景德镇手工瓷业遗存”项目星期六（7月25日）在韩国釜山召开的联合国教科文组织第48届世界遗产大会上通过审议，列入《世界遗产名录》。至此，中国世界遗产总数达61项。 据介绍，“景德镇手工瓷业遗存”位于中国江西省东北部，由镇区瓷业生产中心、湖田古瓷窑址、高岭瓷土矿遗址、长岭瓷石矿遗址和蛟潭窑柴燃料产区五个组成部分构成，包含御窑厂窑址、落马桥窑址、观音阁窑址…"
