    "content": "快科技7月25日消息，今日，一组奥迪A2 E-tron路测图曝光。 新车定位入门级纯电车型，计划在A1和Q2于明年退役后承接其细分市场定位，将成为奥迪在售车型中尺寸最小的一款。 新车将作为A3掀背车与Q2跨界车的纯电对应产品，定位介于掀背车与跨界车之间。 外观方面，整体轮廓接近缩小版Q4 E-tron，同时吸收1999年至2005年间老款A2的圆润设计特征。 由于该车并非直接替代现有单一车型，奥迪可能启用新命名。 据悉，这款车很可能与斯柯达Elroq形成姊妹车型。作为参照，Elroq提供58kWh至79kWh电池版…"
