    "description": "备受关注的携程垄断案7月25日公布了处罚结果：市场监管总局依法对携程集团有限公司（以下简称携程）滥用市场支配地位实施垄断行为作出行政处罚，罚没款合计51.79亿元。 携程垄断案的查处是平台经济反垄断常态化监管的又一重大标志性案件，在很多领域具有突破性意义，记者将从三个“第一”的角度复盘携程垄断案始末。 我国在线旅游领域反垄断第一案 “携程要求我签署‘最优价格条款’，保证在携程的售价必须比其他渠道低，而且佣金从最初的10%左右，到现在部分…",
    "content": "备受关注的携程垄断案7月25日公布了处罚结果：市场监管总局依法对携程集团有限公司（以下简称携程）滥用市场支配地位实施垄断行为作出行政处罚，罚没款合计51.79亿元。 携程垄断案的查处是平台经济反垄断常态化监管的又一重大标志性案件，在很多领域具有突破性意义，记者将从三个“第一”的角度复盘携程垄断案始末。 我国在线旅游领域反垄断第一案 “携程要求我签署‘最优价格条款’，保证在携程的售价必须比其他渠道低，而且佣金从最初的10%左右，到现在部分房型超过25%，利润空间被严重挤压，算上房租、人工、能耗，我的净利润已不足5%。…"
