    "description": "如果你曾经试过在 Mac 上往 NTFS 硬盘里拷东西，应该懂那种感觉——要么拷不进去，要么得装个软件、关 SIP 、重启、再祈祷一切正常。 我们之前做了 BuhoNTFS 1.0 ，能解决读写问题，但说实话，我们自己用着也觉得有些地方不够爽——有时候挂载不够快，有时候传输大文件会卡一下。在之后的版本升级过程中，我们也尝试各种各样的技术思路，但结果都不理想，所以 2.0 我们干脆把底层重写了。 这次不一样的地方： 1. 不关 SIP ，…",
    "content": "如果你曾经试过在 Mac 上往 NTFS 硬盘里拷东西，应该懂那种感觉——要么拷不进去，要么得装个软件、关 SIP 、重启、再祈祷一切正常。 我们之前做了 BuhoNTFS 1.0 ，能解决读写问题，但说实话，我们自己用着也觉得有些地方不够爽——有时候挂载不够快，有时候传输大文件会卡一下。在之后的版本升级过程中，我们也尝试各种各样的技术思路，但结果都不理想，所以 2.0 我们干脆把底层重写了。 这次不一样的地方： 1. 不关 SIP ，不用重启——插上硬盘、开始读写、即插即用 2. 读写更快——针对大文件传输和日常…"
